-- MI-21 guest/staff self-service channels and provider-neutral device contracts.
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_guest_portal_session(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),guest_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_guest(id) ON DELETE RESTRICT,stay_id UUID REFERENCES "{{TENANT_SCHEMA}}".hospitality_guest_stay(id) ON DELETE RESTRICT,token_hash CHAR(64) NOT NULL UNIQUE,status VARCHAR(12) NOT NULL DEFAULT 'ACTIVE',expires_at TIMESTAMPTZ NOT NULL,last_seen_at TIMESTAMPTZ,revoked_at TIMESTAMPTZ,residue_purged_at TIMESTAMPTZ,CONSTRAINT ck_hospitality_portal_session_status CHECK(status IN('ACTIVE','EXPIRED','REVOKED')));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_kiosk_session(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),property_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_property(id) ON DELETE RESTRICT,stay_id UUID REFERENCES "{{TENANT_SCHEMA}}".hospitality_guest_stay(id) ON DELETE RESTRICT,device_code VARCHAR(64) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'STARTED',identity_result JSONB,started_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ,expires_at TIMESTAMPTZ NOT NULL,residue_purged_at TIMESTAMPTZ,CONSTRAINT ck_hospitality_kiosk_status CHECK(status IN('STARTED','VERIFIED','COMPLETED','ABANDONED','EXPIRED')));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_provider_contract(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),property_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_property(id) ON DELETE RESTRICT,provider_type VARCHAR(20) NOT NULL,provider_key VARCHAR(64) NOT NULL,credential_reference VARCHAR(180),contract_version VARCHAR(40),status VARCHAR(24) NOT NULL DEFAULT 'BLOCKED_PROVIDER_INPUT',capabilities JSONB NOT NULL DEFAULT '[]'::jsonb,last_health_at TIMESTAMPTZ,UNIQUE(property_id,provider_type,provider_key),CONSTRAINT ck_hospitality_provider_type CHECK(provider_type IN('DIGITAL_KEY','IOT_ROOM','KIOSK_IDENTITY')));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_iot_device(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),provider_contract_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_provider_contract(id) ON DELETE RESTRICT,room_id UUID REFERENCES "{{TENANT_SCHEMA}}".hospitality_room(id) ON DELETE RESTRICT,external_device_id VARCHAR(160) NOT NULL,device_type VARCHAR(32) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'UNKNOWN',last_seen_at TIMESTAMPTZ,last_state JSONB,UNIQUE(provider_contract_id,external_device_id));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_mobile_operation(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),actor_id UUID NOT NULL,workspace VARCHAR(32) NOT NULL,client_operation_id VARCHAR(128) NOT NULL,operation_type VARCHAR(64) NOT NULL,payload JSONB NOT NULL,result JSONB,status VARCHAR(16) NOT NULL DEFAULT 'RECEIVED',occurred_offline_at TIMESTAMPTZ,received_at TIMESTAMPTZ NOT NULL DEFAULT now(),processed_at TIMESTAMPTZ,UNIQUE(actor_id,workspace,client_operation_id));
CREATE INDEX IF NOT EXISTS ix_hospitality_mobile_sync ON "{{TENANT_SCHEMA}}".hospitality_mobile_operation(actor_id,status,received_at);
